spec:
"""Spec for spiral_order: list every matrix element once, walking clockwise from the top-left (right, down, left, up) and spiralling inwards.

Domain: rectangular matrices of integers with 1..8 rows and 1..8 columns, plus the empty matrix [] that the
unit tests check. Matrices with empty rows (e.g. [[]]) are not generated.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "spiral_order"

CLARIFICATIONS = [
    "Return the elements as a list; an empty matrix [] gives [].",
]


@st.composite
def matrices(draw, distinct=False):
    """Rectangular matrices, biased toward single rows, single columns, squares and 2-wide shapes."""
    m = draw(st.one_of(st.just(1), st.just(2), st.integers(min_value=1, max_value=8)))
    n = draw(st.one_of(st.just(1), st.just(2), st.just(m), st.integers(min_value=1, max_value=8)))
    if distinct:
        flat = draw(st.lists(st.integers(-1000, 1000), min_size=m * n, max_size=m * n, unique=True))
    else:
        flat = draw(st.lists(st.integers(-9, 9), min_size=m * n, max_size=m * n))
    return [flat[r * n:(r + 1) * n] for r in range(m)]


def walk(matrix):
    """Move in the current direction until the next cell is off-grid or already visited, then turn clockwise."""
    m, n = len(matrix), len(matrix[0])
    seen = [[False] * n for _ in range(m)]
    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    r = c = d = 0
    out = []
    for _ in range(m * n):
        out.append(matrix[r][c])
        seen[r][c] = True
        nr, nc = r + dirs[d][0], c + dirs[d][1]
        if not (0 <= nr < m and 0 <= nc < n) or seen[nr][nc]:
            d = (d + 1) % 4
            nr, nc = r + dirs[d][0], c + dirs[d][1]
        r, c = nr, nc
    return out


def rotate_ccw(matrix):
    """Rotate counter-clockwise so that the old last column becomes the new first row."""
    if not matrix:
        return []
    return [list(col) for col in zip(*matrix)][::-1]


@prop("The output matches a step-by-step clockwise walk that turns right whenever it would leave the grid or revisit a cell.",
      matrix=matrices(distinct=True))
def matches_walk(f, matrix):
    assert f(matrix) == walk(matrix)


@prop("The output is the first row followed by the spiral order of the remaining rows rotated counter-clockwise.",
      matrix=matrices())
def recursive_peel(f, matrix):
    rest = rotate_ccw(matrix[1:])
    expected_tail = f(rest) if rest and rest[0] else []
    assert f(matrix) == matrix[0] + expected_tail


@prop("The output is a list containing every matrix entry exactly once.", matrix=matrices(distinct=True))
def is_permutation(f, matrix):
    out = f(matrix)
    assert isinstance(out, list)
    assert sorted(out) == sorted(x for row in matrix for x in row)


@prop("A single-row matrix is returned left to right.", row=st.lists(st.integers(-100, 100), min_size=1, max_size=20))
def single_row(f, row):
    assert f([list(row)]) == row


@prop("A single-column matrix is returned top to bottom.", col=st.lists(st.integers(-100, 100), min_size=1, max_size=20))
def single_column(f, col):
    assert f([[x] for x in col]) == col


@prop("An empty matrix yields an empty list.", dummy=st.just(None))
def empty_matrix(f, dummy):
    assert f([]) == []

reference_solution:
def spiral_order(matrix):
    """
    Returns the elements of the matrix in spiral order.

    Args:
    matrix: 2D list of integers

    Returns:
    list of integers in spiral order
    """
    if not matrix:
        return []

    spiral = []
    while matrix:
        # Take the first row
        spiral.extend(matrix.pop(0))

        # Take the last element of each remaining row
        if matrix and matrix[0]:
            for row in matrix:
                spiral.append(row.pop())

        # Take the last row in reverse order
        if matrix:
            spiral.extend(matrix.pop()[::-1])

        # Take the first element of each remaining row in reverse order
        if matrix and matrix[0]:
            for row in matrix[::-1]:
                spiral.append(row.pop(0))

    return spiral

spec:
"""Spec for count_divisors: map each positive integer to the number of its positive divisors, preserving order.

Domain: lists of positive integers in 1..400 (the statement says nothing about 0 or negative numbers, so they
are not generated), including the empty list.
"""
from math import gcd, isqrt

from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "count_divisors"

CLARIFICATIONS = [
    "The input contains only positive integers; count the positive divisors of each (1 and the number itself included).",
    "Return a list of ints in the same order as the input.",
]

positives = st.one_of(
    st.integers(min_value=1, max_value=400),
    st.sampled_from([1, 2, 3, 4, 9, 16, 36, 64, 97, 128, 360, 400]),
)
arrays = st.one_of(
    st.lists(positives, max_size=15),
    st.builds(lambda x, n: [x] * n, positives, st.integers(1, 5)),
)
PRIMES = [p for p in range(2, 400) if all(p % q for q in range(2, p))]


def brute_count(n):
    return sum(1 for d in range(1, n + 1) if n % d == 0)


@prop("Each output element equals the number of integers in 1..n that divide the corresponding input n.", arr=arrays)
def matches_brute_force(f, arr):
    assert f(arr) == [brute_count(n) for n in arr]


@prop("The output is a list of the same length as the input, and concatenating inputs concatenates outputs.",
      a=arrays, b=arrays)
def elementwise(f, a, b):
    out = f(a + b)
    assert isinstance(out, list)
    assert out == f(a) + f(b)


@prop("1 has exactly one divisor.", n=st.integers(1, 5))
def one_has_one_divisor(f, n):
    assert f([1] * n) == [1] * n


@prop("Every prime has exactly two divisors.", p=st.sampled_from(PRIMES))
def primes_have_two(f, p):
    assert f([p]) == [2]


@prop("The divisor count is multiplicative: d(a*b) == d(a)*d(b) for coprime a and b.",
      a=st.integers(1, 60), b=st.integers(1, 60))
def multiplicative(f, a, b):
    if gcd(a, b) != 1:
        b = 1
    da, db, dab = f([a, b, a * b])
    assert dab == da * db


@prop("A positive integer has an odd number of divisors exactly when it is a perfect square.", n=positives)
def odd_iff_square(f, n):
    (count,) = f([n])
    assert (count % 2 == 1) == (isqrt(n) ** 2 == n)

reference_solution:
def count_divisors(arr):
    """
    Takes an array of integers and returns a new array in which each element is the count of its divisors.
    """
    def divisors(n):
        if n == 1:
            return 1
        count = 0
        for i in range(1, n + 1):
            if n % i == 0:
                count += 1
        return count

    return [divisors(x) for x in arr]

